template:
struct NoHost;
struct Host(String);

struct Builder<S> {
    host: S,
}

impl Builder<NoHost> {
    fn new() -> Self {
        Builder { host: NoHost }
    }
    fn host(
        self,
        h: &str,
    ) -> ⟦ret_ty⟧ {
        Builder {
            host: Host(h.into()),
        }
    }
}

impl Builder<⟦build_st⟧> {
    fn build(self) -> String {
        self.host.0
    }
}

tests:
#[test]
fn builds_when_host_set() {
    let b = Builder::new()
        .host("example.com");
    assert_eq!(b.build(), "example.com");
}
